        "display": false,
        "benches": [
          {
            "name": "The speed of deletes-between on Linux (Ext2)",
            "value": "3.434",
            "unit": "second",
            "extra": "linux_result"
          },
          {
            "name": "The speed of deletes-between on Asterinas (Ext2)",
            "value": "13.564",
            "unit": "second",
            "extra": "aster_result"
          }
        ]
